array-write-current-binding.code:
var a: Array<string> = ["old"]
fn index() -> i64 { print("index"); return 1 }
fn replacement() -> string {
    print("rhs")
    a = ["new0", "new1"]
    return "stored"
}
var written = (a[index()] = replacement())
print(written, a[1])        // 依次输出 index、rhs、stored stored；旧长度不提前拒绝

